head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst75300";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst75300.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#ipt_searchCorpName").bind("change", function() {
                $c.util.getComponent('ipt_repIsuSrtCd').setValue("");
        });
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75300.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

/**
 * @method
 * @name btn_pd_1w_onclick
 * @description 「1주」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1w_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addDate(to, -7); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst75300.pd_1w' }); } };

/**
 * @method
 * @name btn_pd_1m_onclick
 * @description 「1개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst75300.pd_1m' }); } };

/**
 * @method
 * @name btn_pd_3m_onclick
 * @description 「3개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_3m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -3); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst75300.pd_3m' }); } };

/**
 * @method
 * @name btn_pd_6m_onclick
 * @description 「6개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_6m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -6); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst75300.pd_6m' }); } };

/**
 * @method
 * @name btn_pd_1y_onclick
 * @description 「1년」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1y_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addYear(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst75300.pd_1y' }); } };

/**
 * @method
 * @name btn_findCompanyName_onclick
 * @description btn_findCompanyName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findCompanyName_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst75300.btn_findCompanyName_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75300.btn_fnSearchInit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    const sbmOptions = {
        id: "tx_fn_FileDown",
        method: "post",
        action: "/common/fileupload.do",
        ref: "dma_FileDownReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/irroom.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_detailView_ajaxsubmit
 * @description detail View ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_detailView_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_detailView_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/irroom.do",
        ref: "dma_detailViewAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "1 ') */
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.closeDetail();
    const searchForm = $('#searchForm');
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    $c.util.getComponent("dma_FileDownReq").set("method", "searchIRMaterials");
    $c.util.getComponent("dma_FileDownReq").set("forward", "searchirmaterials_sub");
    document.searchForm.ajaxSubmit({ ajaxUrl: '/corpgeneral/irroom.do', ajaxCallBack: scwin.fnSearchCallBack });
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} ipt_resoroomId ipt_resoroomId
 * @param {*} ipt_attachSeq ipt_attachSeq
 * @param {String} ipt_attachFileNm ipt_attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (ipt_resoroomId, ipt_attachSeq, ipt_attachFileNm) {
    $c.util.getComponent("dma_FileDownReq").set("resoroomId", ipt_resoroomId);
    $c.util.getComponent("dma_FileDownReq").set("attachSeq", ipt_attachSeq);
    $c.util.getComponent("dma_FileDownReq").set("attachFileNm", ipt_attachFileNm);
    await scwin.tx_fn_FileDown();
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent('ipt_searchCorpName').setValue(comAbbrv);
    $c.util.getComponent("dma_FileDownReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_FileDownReq").set("searchCodeType", "char");
};

/**
 * @method
 * @name detailView
 * @description detail View 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.detailView = async function (val) {
    $c.util.getComponent("detailContents").setStyle("display", "");
    $c.util.getComponent('ipt_irSeq').setValue(val);
    $c.util.getComponent("dma_FileDownReq").set("method", "searchIRMaterialsDetail");
    $c.util.getComponent("dma_FileDownReq").set("forward", "searchirmaterials_detail");
    await scwin.tx_detailView_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack2
 * @description fn Search Call Back2 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack2 = function (data) {
    $("#detailContents").empty().append(data);
};

/**
 * @method
 * @name closeDetail
 * @description close Detail 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeDetail = function () {
    $("#detailContents").empty();
    $c.util.getComponent("detailContents").setStyle("display", "none");
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearchInit();
        }
    }
};
